const STORAGE='lumo-demo-v2';
let accounts=[{name:'Admin Lumo',role:'admin',roles:['admin'],rateCents:100},{name:'sujif',role:'seller',roles:['seller'],rateCents:100},{name:'joys',role:'seller',roles:['seller'],rateCents:100}];
let activeAccount='Admin Lumo';
const rolesOf=user=>Array.isArray(user?.roles)?user.roles:[user?.role||'seller'];
const hasRole=(user,role)=>rolesOf(user).includes(role);
const activeSales=()=>sales.filter(s=>!s.cancelled);
let sellerChartMetric='pay';
function ensureSellerChart(){if(document.getElementById('seller-chart'))return;const pocket=document.querySelector('.pocket');if(!pocket)return;const section=document.createElement('section');section.className='card panel seller-motivation';section.innerHTML='<div class="panel-head"><div><h2 class="panel-title">Mon évolution</h2><p class="panel-caption">Suis tes ventes et tes gains sur les 7 derniers jours.</p></div><div class="seller-chart-controls" aria-label="Indicateur du graphique"><button class="active" type="button" data-seller-chart="pay">Salaire</button><button type="button" data-seller-chart="sales">Ventes</button></div></div><div id="seller-chart" class="seller-chart" aria-live="polite"></div><div id="seller-chart-summary" class="seller-chart-summary"></div>';pocket.after(section);section.querySelectorAll('[data-seller-chart]').forEach(button=>button.onclick=()=>{sellerChartMetric=button.dataset.sellerChart;section.querySelectorAll('[data-seller-chart]').forEach(item=>item.classList.toggle('active',item===button));renderSellerChart(sellerChartMetric)})}
function renderSellerChart(metric=sellerChartMetric){const chart=document.getElementById('seller-chart'),summary=document.getElementById('seller-chart-summary');if(!chart||!summary)return;const own=sales.filter(s=>s.seller===account().name);const dates=[];const anchor=new Date(Math.max(Date.now(),...own.map(s=>new Date(s.date).getTime()).filter(Number.isFinite)));anchor.setHours(0,0,0,0);for(let offset=6;offset>=0;offset--){const date=new Date(anchor);date.setDate(anchor.getDate()-offset);dates.push(date)}const key=date=>date.toISOString().slice(0,10);const values=dates.map(date=>own.filter(s=>key(new Date(s.date))===key(date)).reduce((total,s)=>total+(metric==='pay'?(s.payCents||0)/100:Object.values(s.products).reduce((units,count)=>units+count,0)),0));const max=Math.max(...values,1);if(!own.length){chart.innerHTML='<div class="seller-chart-empty">Tes premières ventes apparaîtront ici.</div>';summary.innerHTML='<span>Objectif : commence ta première vente</span><b>0 € gagné</b>';return}chart.innerHTML=dates.map((date,index)=>{const value=values[index],display=metric==='pay'?fmt(value):`${value} vente${value>1?'s':''}`;return `<div class="seller-chart-bar"><strong>${display}</strong><i style="height:${Math.max(value?value/max*100:0,4)}%"></i><small>${new Intl.DateTimeFormat('fr-FR',{weekday:'short'}).format(date).replace('.','')}</small></div>`}).join('');const total=values.reduce((sum,value)=>sum+value,0);summary.innerHTML=metric==='pay'?`<span>Gains sur 7 jours</span><b>${fmt(total)}</b>`:`<span>Ventes sur 7 jours</span><b>${total} parfum${total>1?'s':''}</b>`}
sales.forEach(s=>{s.payRateCents=0;s.payCents=0;s.costCents=Object.entries(s.products).reduce((n,[name,q])=>n+Math.round(products.find(p=>p.name===name).cost*100)*q,0);s.feeCents=0});
try{const saved=JSON.parse(localStorage.getItem(STORAGE));if(saved){accounts=saved.accounts.map(user=>({...user,roles:Array.isArray(user.roles)?user.roles:[user.role||'seller']}));sales=saved.sales;saved.stocks.forEach(p=>{let existing=products.find(x=>x.name===p.name);if(existing)existing.stock=p.stock})}}catch{}
const account=()=>accounts.find(a=>a.name===activeAccount);
const pocketFor=name=>activeSales().filter(s=>s.seller===name).reduce((n,s)=>n+(s.payCents||0),0);
function persist(){try{localStorage.setItem(STORAGE,JSON.stringify({accounts,sales,stocks:products}))}catch{toast('Stockage local indisponible : garde cette page ouverte')}}
function apiPost(action,payload){const apiUrl=window.LUMO_CONFIG?.apiUrl;if(!apiUrl)return Promise.resolve({ok:false,offline:true});const authToken=window.LumoAuth?.sessionToken;return fetch(apiUrl,{method:'POST',headers:{'Content-Type':'text/plain;charset=utf-8'},body:JSON.stringify({action,...payload,sessionToken:authToken})}).then(response=>response.json()).catch(error=>{toast('Synchronisation Sheet indisponible');throw error})}
function updatePocket(){const a=account();document.getElementById('pocket-total').textContent=fmt(pocketFor(a.name)/100);document.getElementById('pocket-rate').textContent=fmt(a.rateCents/100)+' / parfum';document.getElementById('pocket-description').textContent=a.name+' · gains des ventes enregistrées';const units=Object.values(selected).reduce((n,q)=>n+q,0);let preview=document.getElementById('pay-preview');if(!preview){preview=document.createElement('p');preview.id='pay-preview';preview.className='payout-value';document.getElementById('summary-price').parentElement.after(preview)}preview.textContent='Gain pour cette vente : '+fmt(units*a.rateCents/100)}
const baseSummary=renderSummary;renderSummary=function(){baseSummary();updatePocket()};
function updateMetrics(){let ca=0,cost=0,pay=0,fees=0;for(const s of sales){ca+=Math.round(s.price*100);cost+=s.costCents||0;pay+=s.payCents||0;fees+=s.feeCents||0}let values=document.querySelectorAll('.kpi-val');[fmt(ca/100),fmt((ca-cost)/100),fmt((ca-cost-pay-fees)/100),String(sales.length)].forEach((v,i)=>values[i].textContent=v);document.querySelectorAll('.kpi-foot')[0].textContent='Total des ventes de démonstration';document.querySelectorAll('.kpi-foot')[2].textContent=fmt(pay/100)+' de rémunérations déduites · frais TikTok à configurer';document.querySelectorAll('.kpi-foot')[3].textContent='Toutes les ventes de la démo';document.querySelector('.seller-list').innerHTML=accounts.map(a=>{let rows=sales.filter(s=>s.seller===a.name),total=rows.reduce((n,s)=>n+s.price,0);return `<div class="seller-row"><div class="avatar">${esc(a.name.slice(0,2).toUpperCase())}</div><div class="seller-meta"><strong>${esc(a.name)}</strong><span>${rows.length} ventes · pocket ${fmt(pocketFor(a.name)/100)}</span></div><div class="seller-total">${fmt(total)}<small>CA généré</small></div><div class="progress"><i style="width:${ca?total*10000/ca:0}%"></i></div></div>`}).join('');document.querySelector('.seller-list').nextElementSibling.lastElementChild.textContent=fmt(sales.length?ca/100/sales.length:0);document.querySelectorAll('.panels .panel-caption')[0].textContent='Montants des ventes de démonstration';document.querySelectorAll('.panels .panel-caption')[1].textContent='CA et gains indicatifs par compte';document.querySelector('.panels .period').disabled=true;document.querySelector('.panels .period').innerHTML='<option>Ventes de la démo</option>';document.querySelectorAll('.panels .period')[1].textContent=sales.length+' ventes';document.querySelector('.chart-legend .legend-total').textContent=fmt(ca/100);const groups={};sales.forEach(s=>{let d=s.date.slice(0,10);groups[d]??={trends:0,shop:0};groups[d][s.shop==='Lumo Shop'?'shop':'trends']+=s.price});let dates=Object.keys(groups).sort().slice(-7),max=Math.max(1,...dates.map(d=>groups[d].trends+groups[d].shop));document.querySelector('.chart').innerHTML=dates.map(d=>{let g=groups[d];return `<div class="bar-group"><div class="bar-stack" title="${esc(d)} : ${fmt(g.trends+g.shop)}"><i class="bar" style="height:${(g.trends+g.shop)/max*100}%"></i><i class="bar alt" style="height:${g.shop/max*100}%"></i></div><span class="bar-label">${d.slice(8)}/${d.slice(5,7)}</span></div>`}).join('')}
const baseSales=renderSales;renderSales=function(){baseSales();document.querySelectorAll('[data-delete]').forEach(el=>el.onclick=()=>{if(!hasRole(account(),'admin'))return;if(!confirm('Supprimer la vente ? Le stock sera rétabli et son gain retiré du pocket.'))return;const sale=sales.find(s=>s.id==el.dataset.delete);Object.entries(sale.products).forEach(([n,q])=>products.find(p=>p.name===n).stock+=q);sales=sales.filter(s=>s!==sale);refresh();toast('Vente supprimée, stock et pocket ajustés')});document.querySelectorAll('[data-edit]').forEach(el=>el.onclick=()=>{if(!hasRole(account(),'admin'))return;const s=sales.find(s=>s.id==el.dataset.edit),value=prompt('Nouveau prix (€) :',s.price);if(value===null)return;const price=Number(value.replace(',','.'));if(!Number.isFinite(price)||price<=0){toast('Saisis un prix positif');return}s.price=Math.round(price*100)/100;refresh();toast('Prix corrigé · gain par flacon inchangé')});document.querySelectorAll('[data-verify]').forEach(el=>el.onchange=()=>{if(!hasRole(account(),'admin'))return;sales.find(s=>s.id==el.dataset.verify).verified=el.checked;refresh()});};
function decorateOrders(){const header=document.querySelector('#sales-list thead tr');if(header&&!header.querySelector('[data-order-status-head]')){const cell=document.createElement('th');cell.dataset.orderStatusHead='true';cell.textContent='Commande';header.insertBefore(cell,header.lastElementChild)}document.querySelectorAll('#sales-body tr').forEach(row=>{const remove=row.querySelector('[data-delete]');if(!remove)return;const sale=sales.find(item=>item.id==remove.dataset.delete);if(!sale)return;const status=document.createElement('td');status.innerHTML=sale.packed?'<span class="stock-status">Validée</span>':'<span class="stock-status low">À emballer</span>';row.insertBefore(status,row.lastElementChild);const actions=row.querySelector('.row-actions');if(!actions||(!hasRole(account(),'admin')&&!hasRole(account(),'packer')))return;if(!sale.packed){const approve=document.createElement('button');approve.className='icon-btn';approve.title='Valider la commande';approve.textContent='✓';approve.dataset.pack=sale.id;actions.prepend(approve)}const cancel=document.createElement('button');cancel.className='icon-btn';cancel.title='Annuler et retirer la commande';cancel.textContent='×';cancel.dataset.cancel=sale.id;actions.prepend(cancel)});document.querySelectorAll('[data-pack]').forEach(button=>button.onclick=()=>{if(!hasRole(account(),'admin')&&!hasRole(account(),'packer'))return;const sale=sales.find(item=>item.id==button.dataset.pack);if(!sale)return;sale.packed=true;apiPost('pack',{id:sale.id});refresh();toast('Commande validée pour préparation')});document.querySelectorAll('[data-cancel]').forEach(button=>button.onclick=()=>{if(!hasRole(account(),'admin')&&!hasRole(account(),'packer'))return;const sale=sales.find(item=>item.id==button.dataset.cancel);if(!sale||!confirm('Retirer cette commande annulée ? Le vendeur ne sera pas rémunéré.'))return;Object.entries(sale.products).forEach(([name,count])=>products.find(product=>product.name===name).stock+=count);apiPost('cancel',{id:sale.id});sales=sales.filter(item=>item!==sale);refresh();toast('Commande retirée · pocket et stock ajustés')})}
function refresh(){renderStock();renderProducts();renderSummary();renderSales();decorateOrders();updateMetrics();renderSellerChart();persist()}
setScreen=function(id){const user=account();if(id==='dashboard'&&!hasRole(user,'admin'))return;if(id==='sales-list'&&!hasRole(user,'admin')&&!hasRole(user,'packer'))return;if(id==='sales-entry'&&!hasRole(user,'admin')&&!hasRole(user,'seller'))return;const screen=id==='stock'||id==='sales-list'?'dashboard':id;document.querySelectorAll('.screen').forEach(s=>s.classList.toggle('active',s.id===screen));document.querySelectorAll('.nav-btn,.mobile-bottom button').forEach(b=>b.classList.toggle('active',b.dataset.target===id));document.getElementById('crumb-label').textContent=screen==='dashboard'?'Vue d’ensemble':id==='sales-list'?'Commandes à emballer':'Nouvelle vente';if(id!==screen)document.getElementById(id).scrollIntoView({behavior:'smooth',block:'start'});else window.scrollTo({top:0,behavior:'smooth'})};
function populateAccounts(){const options=accounts.map(a=>`<option>${esc(a.name)}</option>`).join('');document.getElementById('demo-account').innerHTML=options;document.getElementById('demo-account').value=activeAccount;document.getElementById('sale-seller').innerHTML=options;document.getElementById('sale-seller').value=activeAccount;document.getElementById('seller-filter').innerHTML='<option value="">Tous les vendeurs</option>'+options}
document.getElementById('demo-account').onchange=e=>{activeAccount=e.target.value;document.body.classList.toggle('seller-mode',hasRole(account(),'seller'));document.body.classList.toggle('packer-mode',hasRole(account(),'packer')&&!hasRole(account(),'admin'));document.getElementById('sale-seller').value=activeAccount;document.querySelector('.profile strong').textContent=activeAccount;document.querySelector('.profile span').textContent=hasRole(account(),'admin')?'Administrateur':hasRole(account(),'packer')?'Vendeur · Emballeur':'Vendeur';document.querySelector('.profile .avatar').textContent=activeAccount.slice(0,2).toUpperCase();selected={};updatePackerControl();refresh();setScreen(hasRole(account(),'admin')?'dashboard':hasRole(account(),'seller')?'sales-entry':'sales-list')};
document.getElementById('save-sale').onclick=()=>{let buyer=document.getElementById('sale-buyer').value.trim(),price=Number(document.getElementById('sale-price').value),date=document.getElementById('sale-date').value,link=document.getElementById('sale-link').value.trim();let items=Object.fromEntries(Object.entries(selected).filter(([,q])=>q>0));if(!buyer||!date||!Number.isFinite(price)||price<=0||!Object.keys(items).length){toast('Renseigne le pseudo, la date, les parfums et un prix positif');return}if(link){try{const u=new URL(link);if(!['https:','http:'].includes(u.protocol))throw 0}catch{toast('Le lien du bordereau doit être une URL valide');return}}for(const [name,q] of Object.entries(items)){if(q>products.find(p=>p.name===name).stock){toast('Stock insuffisant pour '+name);return}}const units=Object.values(items).reduce((n,q)=>n+q,0),rate=account().rateCents;const cost=Object.entries(items).reduce((n,[name,q])=>n+Math.round(products.find(p=>p.name===name).cost*100)*q,0);for(const [name,q] of Object.entries(items))products.find(p=>p.name===name).stock-=q;const sale={id:Date.now(),date,buyer,price:Math.round(price*100)/100,seller:activeAccount,shop:document.getElementById('sale-shop').value,products:items,verified:false,link,payRateCents:rate,payCents:rate*units,costCents:cost,feeCents:0,status:'pending'};sales.unshift(sale);apiPost('create',{id:sale.id,date:sale.date,buyer:sale.buyer,seller:sale.seller,shop:sale.shop,products:sale.products,priceCents:Math.round(sale.price*100),verified:sale.verified,receiptUrl:sale.link,payRateCents:sale.payRateCents,payCents:sale.payCents,costCents:sale.costCents,feeCents:sale.feeCents});selected={};['sale-buyer','sale-price','sale-link'].forEach(id=>document.getElementById(id).value='');document.getElementById('sale-date').value=localDate();refresh();toast('Vente enregistrée · +'+fmt(rate*units/100)+' dans ton pocket')};
function renderRates(){document.getElementById('rate-list').innerHTML=accounts.map((a,i)=>`<div class="rate-row"><label for="rate-${i}">${esc(a.name)}<small>Pocket : ${fmt(pocketFor(a.name)/100)}</small></label><div><input class="input" id="rate-${i}" aria-label="Tarif par parfum pour ${esc(a.name)}" type="number" min="0" max="10000" step="0.01" value="${(a.rateCents/100).toFixed(2)}"><small>€ / parfum</small></div><button class="btn btn-primary" data-rate="${i}">Appliquer</button></div>`).join('');document.querySelectorAll('[data-rate]').forEach(b=>b.onclick=()=>{if(account().role!=='admin')return;let i=Number(b.dataset.rate),raw=document.getElementById('rate-'+i).value,value=Number(raw);if(!raw||!Number.isFinite(value)||value<0||value>10000){toast('Saisis un tarif entre 0 et 10 000 €');return}accounts[i].rateCents=Math.round(value*100);refresh();renderRates();toast('Tarif mis à jour pour les prochaines ventes')})}
const baseRenderRates=renderRates;renderRates=function(){baseRenderRates();document.querySelectorAll('#rate-list .rate-row').forEach(row=>{const apply=row.querySelector('[data-rate]'),index=Number(apply?.dataset.rate),target=accounts[index];if(!target)return;const roleButton=document.createElement('button');roleButton.className='btn';roleButton.type='button';roleButton.textContent=hasRole(target,'packer')?'Retirer emballeur':'Attribuer emballeur';roleButton.onclick=()=>{if(!hasRole(account(),'admin')&&target.name!==account().name)return;target.roles=rolesOf(target);target.role=target.roles.includes('packer')?'seller':'packer';target.roles=target.roles.includes('packer')?target.roles.filter(role=>role!=='packer'):target.roles.concat('packer');persist();renderRates();populateAccounts();toast(target.roles.includes('packer')?'Rôle emballeur activé':'Rôle emballeur retiré')};row.append(roleButton)})};
document.getElementById('open-pay').onclick=()=>{if(!hasRole(account(),'admin'))return;renderRates();document.getElementById('pay-dialog').showModal()};document.getElementById('close-pay').onclick=()=>document.getElementById('pay-dialog').close();
function ensureAccountFields(){const input=document.getElementById('new-seller');if(!input||document.getElementById('new-username'))return;input.placeholder='Nom affiché';const username=document.createElement('input');username.id='new-username';username.className='input';username.placeholder='Identifiant';username.maxLength=40;const password=document.createElement('input');password.id='new-password';password.className='input';password.placeholder='Mot de passe temporaire';password.type='password';password.maxLength=100;input.parentElement.parentElement.insertBefore(username,input.parentElement);input.parentElement.parentElement.insertBefore(password,input.parentElement);document.getElementById('add-seller').onclick=()=>{if(!hasRole(account(),'admin'))return;const name=input.value.trim(),usernameValue=username.value.trim(),passwordValue=password.value;if(!name||!usernameValue||!passwordValue){toast('Renseigne le nom, l’identifiant et le mot de passe');return}apiPost('createAccount',{name,username:usernameValue,password:passwordValue}).then(result=>{if(!result.ok)throw new Error(result.error||'Création refusée');accounts.push({name,role:'seller',roles:['seller'],rateCents:100});populateAccounts();refresh();renderRates();input.value='';username.value='';password.value='';toast('Compte créé · transmets ses identifiants en privé')}).catch(error=>toast(error.message))}}
document.querySelector('.stock-panel .btn').onclick=()=>toast('Stocks mis à jour automatiquement par les ventes de démo');document.querySelector('.shop-switch select').onchange=()=>toast('Choisis la boutique lors de la saisie de chaque vente');document.querySelector('.heading .eyebrow').textContent=new Date().toLocaleDateString('fr-FR',{weekday:'long',day:'numeric',month:'long',year:'numeric'});document.querySelector('.heading .subheading').textContent='Vos ventes, vos stocks et les gains de votre équipe.';
function ensurePackerControl(){const pocket=document.querySelector('.pocket');if(!pocket||document.getElementById('packer-toggle'))return;const button=document.createElement('button');button.id='packer-toggle';button.className='btn';button.type='button';pocket.append(button);button.onclick=()=>{const user=account();user.roles=rolesOf(user);const enabled=hasRole(user,'packer');user.roles=enabled?user.roles.filter(role=>role!=='packer'):user.roles.concat('packer');user.role=hasRole(user,'seller')?'seller':'packer';document.body.classList.toggle('packer-mode',!enabled&&!hasRole(user,'admin'));document.querySelector('.profile span').textContent=hasRole(user,'admin')?'Administrateur':hasRole(user,'packer')?'Vendeur · Emballeur':'Vendeur';persist();updatePackerControl();populateAccounts();setScreen(!enabled?'sales-list':'sales-entry');toast(enabled?'Mode emballeur retiré':'Mode emballeur activé')};updatePackerControl()}
function updatePackerControl(){const button=document.getElementById('packer-toggle');if(button)button.textContent=hasRole(account(),'packer')?'Quitter le mode emballeur':'Activer le mode emballeur'}
function applyAuthenticatedAccount(user){if(!user?.name)return;const match=accounts.find(item=>item.name===user.name||item.name===user.username);if(!match)return;activeAccount=match.name;document.body.classList.add('auth-live');document.querySelector('#sale-seller')?.closest('.field')?.classList.add('auth-account-field');document.getElementById('demo-account').value=activeAccount;document.getElementById('sale-seller').value=activeAccount;document.querySelector('.profile strong').textContent=activeAccount;document.querySelector('.profile span').textContent=hasRole(match,'admin')?'Administrateur':hasRole(match,'packer')?'Vendeur · Emballeur':'Vendeur';document.querySelector('.profile .avatar').textContent=activeAccount.slice(0,2).toUpperCase();document.body.classList.toggle('seller-mode',hasRole(match,'seller'));document.body.classList.toggle('packer-mode',hasRole(match,'packer')&&!hasRole(match,'admin'));selected={};refresh();setScreen(hasRole(match,'admin')?'dashboard':'sales-entry')}
document.addEventListener('lumo-authenticated',event=>applyAuthenticatedAccount(event.detail));
if(window.LumoAuth?.name&&accounts.some(user=>user.name===window.LumoAuth.name)){activeAccount=window.LumoAuth.name;document.body.classList.add('auth-live')}ensureSellerChart();ensurePackerControl();ensureAccountFields();document.querySelector('#sale-seller')?.closest('.field')?.classList.add('auth-account-field');document.body.classList.toggle('seller-mode',hasRole(account(),'seller'));document.body.classList.toggle('packer-mode',hasRole(account(),'packer')&&!hasRole(account(),'admin'));populateAccounts();refresh();
